program Example;
{$mode objfpc}
uses SysUtils;
type TPoint = record X, Y: Double; end;
const ANSWER = 42;
function Square(Value: Double): Double;
begin
  Result := Value * Value;
end;
var Point: TPoint;
begin
  Point.X := 3.14;
  WriteLn('Hello ', Square(Point.X), ANSWER);
end.
